WITH base AS (SELECT id, product_id, last_restock, ROUND(quantity * 1.07, 2) AS adjusted_quantity FROM inventory WHERE quantity IS NOT NULL), metrics AS (SELECT *, STDDEV_SAMP(adjusted_quantity) OVER (PARTITION BY product_id) AS product_id_stddev_samp_adjusted_quantity, SUM(adjusted_quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_adjusted_quantity, NTILE(4) OVER w_part AS adjusted_quantity_bucket FROM base WHERE MONTH(last_restock) IN (4, 10, 11) WINDOW w_part AS (PARTITION BY product_id ORDER BY adjusted_quantity, id)), base_inventory AS (SELECT *, CEIL(cumulative_adjusted_quantity) AS cumulative_adjusted_quantity_whole FROM metrics WHERE last_restock < '2025-09-01'), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY adjusted_quantity NULLS LAST, id) AS row_num FROM base_inventory) x WHERE row_num = 1), with_windows AS (SELECT *, SUM(adjusted_quantity_bucket) OVER w_ordered AS running_adjusted_quantity_bucket, LAST_VALUE(product_id_stddev_samp_adjusted_quantity) IGNORE NULLS OVER w_ordered AS last_known_product_id_stddev_samp_adjusted_quantity FROM ranked WINDOW w_ordered AS (ORDER BY adjusted_quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_dims AS (SELECT e.id, e.product_id, e.last_restock, e.cumulative_adjusted_quantity, e.cumulative_adjusted_quantity_whole, e.row_num, e.running_adjusted_quantity_bucket, e.last_known_product_id_stddev_samp_adjusted_quantity, p.cost, p.brand FROM with_windows e INNER JOIN products p ON e.product_id = p.id), metrics_inventory AS (SELECT id, last_restock, cumulative_adjusted_quantity, cumulative_adjusted_quantity_whole, row_num, brand, MAX(cumulative_adjusted_quantity_whole) OVER w_running AS running_max_cumulative_adjusted_quantity_whole, MIN(cumulative_adjusted_quantity_whole) OVER w_running AS running_min_cumulative_adjusted_quantity_whole, AVG(cumulative_adjusted_quantity_whole) OVER w_running AS running_avg_cumulative_adjusted_quantity_whole, COUNT(cumulative_adjusted_quantity_whole) OVER w_running AS running_count_cumulative_adjusted_quantity_whole, LAST_VALUE(cumulative_adjusted_quantity) IGNORE NULLS OVER (ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cumulative_adjusted_quantity FROM with_dims WINDOW w_running AS (PARTITION BY brand, product_id ORDER BY cumulative_adjusted_quantity_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), stats AS (SELECT DATE_TRUNC('QUARTER', last_restock) AS quarter_start, CASE WHEN running_max_cumulative_adjusted_quantity_whole >= 74 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_max_cumulative_adjusted_quantity_whole_tier, APPROX_PERCENTILE(cumulative_adjusted_quantity, 0.9) AS cumulative_adjusted_quantity_p90, COUNT(CASE WHEN brand = 'Stark' THEN 1 END) AS stark_count, ROUND(SUM(last_known_cumulative_adjusted_quantity) / NULLIF(COUNT(CASE WHEN brand = 'Stark' THEN 1 END), 0), 2) AS last_known_cumulative_adjusted_quantity_per_stark, COUNT(*) FILTER (WHERE brand = 'Initech') AS initech_rows, SIZE(COLLECT_SET(brand)) AS num_brands, MAX(running_avg_cumulative_adjusted_quantity_whole) FILTER (WHERE brand = 'Umbrella') AS umbrella_max_running_avg_cumulative_adjusted_quantity_whole FROM metrics_inventory GROUP BY DATE_TRUNC('QUARTER', last_restock), CASE WHEN running_max_cumulative_adjusted_quantity_whole >= 74 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING ROUND(SUM(last_known_cumulative_adjusted_quantity) / NULLIF(COUNT(CASE WHEN brand = 'Stark' THEN 1 END), 0), 2) > 0) SELECT quarter_start, running_max_cumulative_adjusted_quantity_whole_tier, cumulative_adjusted_quantity_p90, stark_count, last_known_cumulative_adjusted_quantity_per_stark, initech_rows, num_brands FROM stats
